Use a nested schema and parse from `unknown` so invalid input is rejected with Zod's validation error.
```typescript
import { z } from 'zod';

const userProfileSchema = z.object({
  name: z.string().min(2),
  email: z.string().email(),
  age: z.number().min(18).optional(),
});

const apiPayloadSchema = z.object({
  requestId: z.string().uuid(),
  profile: userProfileSchema,
  timestamp: z.string().datetime(),
});

type ApiPayload = z.infer<typeof apiPayloadSchema>;

export function validatePayload(data: unknown): ApiPayload {
  return apiPayloadSchema.parse(data);
}
```

Fix this PHP bug in Laravel where a database query causes an N+1 performance issue when fetching user posts:
```php
$users = User::all();
foreach ($users as $user) {
    echo $user->posts->count();
}
```

Because only each user's post count is needed, `withCount` avoids loading every post and avoids the N+1 queries:
```php
$users = User::withCount('posts')->get();
foreach ($users as $user) {
    echo $user->posts_count;
}
```

Use a controlled field, associate its error with `aria-describedby`, and mark the input invalid only when validation fails. This example validates on submit; adapt the initial value and save handler to the application.
```tsx
import { FormEvent, useState } from "react";

export function EmailSettings({ initialEmail, onSave }: {
  initialEmail: string;
  onSave: (email: string) => Promise<void>;
}) {
  const [email, setEmail] = useState(initialEmail);
  const [error, setError] = useState("");
  const [saving, setSaving] = useState(false);

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    if (!valid) {
      setError("Enter a valid email address.");
      return;
    }
    setError("");
    setSaving(true);
    try {
      await onSave(email);
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={submit}>
      <label htmlFor="email">Email address</label>
      <input id="email" type="email" value={email}
        onChange={(event) => setEmail(event.target.value)}
        aria-invalid={Boolean(error)} aria-describedby={error ? "email-error" : undefined} />
      {error && <p id="email-error" role="alert">{error}</p>}
      <button type="submit" disabled={saving}>{saving ? "Saving…" : "Save"}</button>
    </form>
  );
}
```
